-- =====================================================================================
-- Saturday mock dispensing (Jan 2025 - Oct 23 2026) for the Predictive Medicine Demand forecast.
-- The clinic works Monday to Saturday (only Sunday is closed) but the earlier seeds only covered Mon-Fri,
-- so the forecast saw Saturday as an empty day. This adds 203 clinic_visits (VSAT-*) with one
-- consultation_dispensation each (DSAT-*) on 75 Saturdays.
-- Each Saturday row copies a random Mon-Fri dispensation from the SAME week (same medicine batch, quantity,
-- unit and complaint), so every medicine is still only dispensed for a complaint it is linked to and
-- quantities respect the dispense limit. Volume is about 28% of an average Mon-Fri day
-- (half-day clinic, morning visits 08:00-11:45). Saturdays in weeks with no weekday activity (breaks) are skipped.
-- Stock is NOT changed. Safe to re-run: deletes its own VSAT-% / DSAT-% rows first.
-- Generated by a deterministic script; 0 break-week Saturdays skipped.
-- =====================================================================================

USE ClinicManagementSystem;
SET time_zone = '+08:00';
SET SQL_SAFE_UPDATES = 0;
START TRANSACTION;

DELETE FROM consultation_dispensation WHERE consultation_dispense_id LIKE 'DSAT-%';
DELETE FROM clinic_visits WHERE visit_id LIKE 'VSAT-%';





COMMIT;
